import subprocess,json,pathlib
root=pathlib.Path('/scratch/alpine/paco0228/ACE/results/ace_llm_intervention_campaign_artificial_20261108_01')
r={}
for k,c in {'queue':['squeue','-j','35385156','-h','-o','%i|%T|%R|%a'],'accounting':['sacct','-j','35385156','-n','-P','--format=JobID,State,ExitCode,ElapsedRaw,AllocCPUS,AllocTRES%120,MaxRSS,TotalCPU']}.items():
 p=subprocess.run(c,capture_output=True,text=True,timeout=15);r[k]={'stdout':p.stdout,'stderr':p.stderr,'returncode':p.returncode}
for name in ['cpu01/failure.json','cpu01/supervisor.json','cpu01/worker/failure.json','cpu01/worker/artifacts/terminal.json']:
 p=root/name
 if p.exists():r[name]=p.read_text()[:16000]
